-- Together Wealth: run once in the Supabase SQL editor.
create extension if not exists "uuid-ossp";

create table households (id uuid primary key default uuid_generate_v4(), name text not null default '我们的家庭', created_at timestamptz not null default now());
create table household_members (household_id uuid references households(id) on delete cascade, user_id uuid references auth.users(id) on delete cascade, display_name text not null, role text not null check (role in ('owner','member')), primary key (household_id, user_id));
create table assets (id uuid primary key default uuid_generate_v4(), household_id uuid not null references households(id) on delete cascade, name text not null, category text not null default 'other', owner text not null, institution text, notes text, created_at timestamptz not null default now(), archived_at timestamptz);
create table asset_snapshots (id uuid primary key default uuid_generate_v4(), asset_id uuid not null references assets(id) on delete cascade, value numeric(14,2) not null check (value >= 0), currency text not null default 'CAD', captured_at date not null default current_date, source text not null default 'manual' check (source in ('manual','import','sync')), created_by uuid references auth.users(id), created_at timestamptz not null default now(), unique(asset_id, captured_at));
create table goals (id uuid primary key default uuid_generate_v4(), household_id uuid not null references households(id) on delete cascade, name text not null, target_value numeric(14,2) not null, target_date date, created_at timestamptz not null default now());
create table advisor_conversations (id uuid primary key default uuid_generate_v4(), household_id uuid not null references households(id) on delete cascade, role text not null check (role in ('user','assistant')), content text not null, created_at timestamptz not null default now());
create table advisor_alerts (id uuid primary key default uuid_generate_v4(), household_id uuid not null references households(id) on delete cascade, title text not null, body text not null, kind text not null default 'insight', read_at timestamptz, created_at timestamptz not null default now());

alter table households enable row level security; alter table household_members enable row level security; alter table assets enable row level security; alter table asset_snapshots enable row level security; alter table goals enable row level security; alter table advisor_conversations enable row level security; alter table advisor_alerts enable row level security;
create policy "members can read household" on households for select using (id in (select household_id from household_members where user_id = auth.uid()));
create policy "members can manage household assets" on assets for all using (household_id in (select household_id from household_members where user_id = auth.uid())) with check (household_id in (select household_id from household_members where user_id = auth.uid()));
create policy "members can manage snapshots" on asset_snapshots for all using (asset_id in (select id from assets where household_id in (select household_id from household_members where user_id = auth.uid()))) with check (asset_id in (select id from assets where household_id in (select household_id from household_members where user_id = auth.uid())));
create policy "members can manage goals" on goals for all using (household_id in (select household_id from household_members where user_id = auth.uid())) with check (household_id in (select household_id from household_members where user_id = auth.uid()));
create policy "members can access conversations" on advisor_conversations for all using (household_id in (select household_id from household_members where user_id = auth.uid())) with check (household_id in (select household_id from household_members where user_id = auth.uid()));
create policy "members can access alerts" on advisor_alerts for all using (household_id in (select household_id from household_members where user_id = auth.uid())) with check (household_id in (select household_id from household_members where user_id = auth.uid()));
